#include <iostream>
using namespace std;

int main() {
    const int n = {n};
    long long pairs = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            pairs = pairs + 1;
        }
    }
    cout << pairs << endl;
    return 0;
}
